package shop.pricing;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.Clock;
import java.time.Instant;
import org.springframework.stereotype.Service;

@Service
public class PricingService {

    private final CouponRepository coupons;
    private final Clock clock;

    public PricingService(CouponRepository coupons, Clock clock) {
        this.coupons = coupons;
        this.clock = clock;
    }

    public BigDecimal total(BigDecimal subtotal, String couponCode) {
        if (couponCode == null) {
            return subtotal;
        }
        Coupon coupon = coupons.findByCode(couponCode)
                .orElseThrow(() -> new UnknownCouponException(couponCode));
        Instant now = clock.instant();
        if (now.isAfter(coupon.expiresAt())) {
            throw new ExpiredCouponException(couponCode);
        }
        BigDecimal discount = subtotal.multiply(coupon.percent())
                .divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_UP);
        return subtotal.subtract(discount);
    }
}

