import java.util.*;

public class ContextCacheDemo {
    record ContextKey(String config, Set<String> mockBeans, Map<String, String> properties) { }

    static final Map<ContextKey, Object> CACHE = new HashMap<>();
    static int startups = 0;

    static Object contextFor(ContextKey key) throws InterruptedException {
        Object ctx = CACHE.get(key);
        if (ctx == null) {
            Thread.sleep(150);                 // stands for a 150 ms context start-up
            startups++;
            ctx = new Object();
            CACHE.put(key, ctx);
        }
        return ctx;
    }

    static ContextKey key(Set<String> mocks, Map<String, String> props) {
        return new ContextKey("ShopApplication", mocks, props);
    }

    public static void main(String[] args) throws Exception {
        List<ContextKey> suite = List.of(
            key(Set.of(), Map.of()),                                        // OrderServiceIT
            key(Set.of("PaymentClient"), Map.of()),                         // CheckoutIT
            key(Set.of(), Map.of()),                                        // InventoryIT
            key(Set.of("PaymentClient"), Map.of("shop.fast", "true")),      // PromoIT
            key(Set.of("PaymentClient", "Mailer"), Map.of()),               // NotifyIT
            key(Set.of(), Map.of()),                                        // ReportIT
            key(Set.of("PaymentClient"), Map.of())                          // RefundIT
        );
        long t0 = System.nanoTime();
        for (ContextKey k : suite) contextFor(k);
        long ms = (System.nanoTime() - t0) / 1_000_000;
        System.out.println("test classes     : " + suite.size());
        System.out.println("context start-ups: " + startups
                + " (distinct keys: " + new HashSet<>(suite).size() + ")");
        System.out.println("elapsed          : ~" + (ms / 50 * 50) + " ms");
        // same suite with one shared configuration (mock declared once, in a shared base class)
        CACHE.clear(); startups = 0;
        ContextKey shared = key(Set.of("PaymentClient"), Map.of());
        t0 = System.nanoTime();
        for (int i = 0; i < suite.size(); i++) contextFor(shared);
        ms = (System.nanoTime() - t0) / 1_000_000;
        System.out.println("shared config    : " + startups + " start-up, ~"
                + (ms / 50 * 50) + " ms");
    }
}

