import com.sun.net.httpserver.HttpServer;
import java.io.IOException;
import java.net.InetSocketAddress;
import java.net.URI;
import java.net.http.*;
import java.time.Duration;
import java.util.concurrent.Executors;
import java.util.concurrent.atomic.AtomicInteger;

public class StubServerDemo {
    public static void main(String[] args) throws Exception {
        AtomicInteger calls = new AtomicInteger();
        HttpServer stub = HttpServer.create(new InetSocketAddress("127.0.0.1", 21501), 0);
        stub.createContext("/payments", ex -> {
            int n = calls.incrementAndGet();
            try {
                if (n == 1) Thread.sleep(400);                 // first call: slow upstream
                byte[] body = (n == 2 ? "{\"error\":\"unavailable\"}"
                                      : "{\"status\":\"OK\"}").getBytes();
                ex.getResponseHeaders().add("Content-Type", "application/json");
                ex.sendResponseHeaders(n == 2 ? 503 : 200, body.length);
                ex.getResponseBody().write(body);
            } catch (InterruptedException | IOException ignored) {
            } finally { ex.close(); }
        });
        stub.setExecutor(Executors.newFixedThreadPool(4));
        stub.start();

        HttpClient client = HttpClient.newBuilder().connectTimeout(Duration.ofMillis(200)).build();
        for (int i = 1; i <= 3; i++) {
            HttpRequest req = HttpRequest.newBuilder(URI.create("http://127.0.0.1:21501/payments"))
                    .timeout(Duration.ofMillis(150))
                    .POST(HttpRequest.BodyPublishers.noBody()).build();
            long t0 = System.nanoTime();
            String outcome;
            try {
                HttpResponse<String> r = client.send(req, HttpResponse.BodyHandlers.ofString());
                outcome = r.statusCode() + " " + r.body();
            } catch (HttpTimeoutException e) {
                outcome = "timeout after ~150 ms (" + e.getClass().getSimpleName() + ")";
            }
            System.out.printf("call %d -> %s [%d ms]%n", i, outcome,
                    (System.nanoTime() - t0) / 1_000_000);
        }
        stub.stop(0);
        System.exit(0);
    }
