import java.util.*;
import java.util.concurrent.atomic.LongAdder;

public class MiniMetrics {

    /** Cumulative histogram with fixed upper bounds in ms (Prometheus "le" semantics). */
    static class Histogram {
        final double[] bounds;
        final long[] counts;
        double sum; long count;
        Histogram(double... bounds) { this.bounds = bounds; this.counts = new long[bounds.length]; }
        void record(double ms) {
            sum += ms; count++;
            for (int i = 0; i < bounds.length; i++) if (ms <= bounds[i]) counts[i]++;
        }
        /** Estimate a quantile by linear interpolation inside the bucket (as Prometheus does). */
        double quantile(double q) {
            double rank = q * count;
            double lowBound = 0; long lowCount = 0;
            for (int i = 0; i < bounds.length; i++) {
                if (counts[i] >= rank) {
                    return lowBound + (bounds[i] - lowBound) * (rank - lowCount)
                            / (counts[i] - lowCount);
                }
                lowBound = bounds[i]; lowCount = counts[i];
            }
            return bounds[bounds.length - 1];
        }
    }

    public static void main(String[] args) {
        Random rnd = new Random(42);
        Histogram h = new Histogram(10, 25, 50, 100, 250, 500, 1000, 2500);
        List<Double> raw = new ArrayList<>();
        for (int i = 0; i < 2000; i++) {
            double ms = rnd.nextDouble() < 0.96 ? 15 + rnd.nextDouble() * 45     // fast path
                                                : 800 + rnd.nextDouble() * 400;  // slow path
            h.record(ms); raw.add(ms);
        }
        Collections.sort(raw);
        System.out.printf("mean        = %.1f ms%n", h.sum / h.count);
        System.out.printf("p50 (exact) = %.1f ms, p99 (exact) = %.1f ms%n",
                raw.get(1000), raw.get(1980));
        System.out.printf("p50 (histo) = %.1f ms, p99 (histo) = %.1f ms%n",
                h.quantile(0.50), h.quantile(0.99));

        String labels = "method=\"GET\",uri=\"/orders/{id}\",status=\"200\"";
        System.out.println();
        System.out.println("# HELP http_server_requests_seconds Request latency");
        System.out.println("# TYPE http_server_requests_seconds histogram");
        for (int i = 0; i < h.bounds.length; i++) {
            System.out.printf("http_server_requests_seconds_bucket{%s,le=\"%s\"} %d%n",
                    labels, fmt(h.bounds[i] / 1000.0), h.counts[i]);
        }
        System.out.printf("http_server_requests_seconds_bucket{%s,le=\"+Inf\"} %d%n",
                labels, h.count);
        System.out.printf("http_server_requests_seconds_count{%s} %d%n", labels, h.count);
        System.out.printf("http_server_requests_seconds_sum{%s} %.3f%n", labels, h.sum / 1000.0);

        // cardinality: series = product of distinct tag values
        System.out.println();
        int methods = 4, statuses = 6, instances = 10, buckets = h.bounds.length + 3;
        long templated = (long) 25 * methods * statuses * instances * buckets;
        long perUserId = (long) 100_000 * methods * statuses * instances * buckets;
        System.out.println("series with 25 templated URIs : " + templated);
        System.out.println("series with 100000 raw URIs   : " + perUserId);
    }

    static String fmt(double d) {
        return d == Math.rint(d) ? String.valueOf((long) d) : String.valueOf(d);
    }
}

