import io.micrometer.core.instrument.Counter;
import io.micrometer.core.instrument.Gauge;
import io.micrometer.core.instrument.MeterRegistry;
import io.micrometer.core.instrument.Timer;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Supplier;
import org.springframework.stereotype.Component;

@Component
public class OrderMetrics {

    private final Counter placed;
    private final Counter rejected;
    private final Timer paymentTimer;
    private final AtomicInteger backlog = new AtomicInteger();

    public OrderMetrics(MeterRegistry registry) {
        this.placed = Counter.builder("orders.placed")
                .description("Orders accepted").register(registry);
        this.rejected = Counter.builder("orders.rejected")
                .tag("reason", "out_of_stock")               // bounded set of values only
                .register(registry);
        this.paymentTimer = Timer.builder("orders.payment")
                .description("Payment gateway latency")
                .publishPercentileHistogram()
                .register(registry);
        Gauge.builder("orders.backlog", backlog, AtomicInteger::get).register(registry);
    }

    public void orderPlaced() { placed.increment(); }
    public void orderRejected() { rejected.increment(); }
    public void backlogChanged(int delta) { backlog.addAndGet(delta); }

    public <T> T timePayment(Supplier<T> call) {
        return paymentTimer.record(call);
    }
}

