import java.util.*;

/** Virtual-time model of kubelet probe handling for one container (seconds). */
public class ProbeSim {
    record Probe(int initialDelay, int period, int failureThreshold) { }

    static void run(String title, int appStart, Probe startup, Probe liveness, int horizon) {
        System.out.println("== " + title);
        int restarts = 0, containerStart = 0, failures = 0;
        boolean started = startup == null, ready = false;
        for (int t = 1; t <= horizon; t++) {
            int age = t - containerStart;
            boolean appUp = age >= appStart;                              // HTTP endpoint answers
            if (appUp && !ready && started) {
                ready = true;
                System.out.printf("t=%3d s  READY (restart %d)%n", t, restarts);
            }
            if (!started) {
                int since = age - startup.initialDelay();
                if (since >= 0 && since % startup.period() == 0) {
                    if (appUp) {
                        started = true; failures = 0;
                        System.out.printf("t=%3d s  startup probe OK%n", t);
                    } else if (++failures >= startup.failureThreshold()) {
                        restarts++; containerStart = t; failures = 0; ready = false;
                        System.out.printf("t=%3d s  startup probe failed %d times: KILLED%n",
                                t, startup.failureThreshold());
                    }
                }
                continue;
            }
            int lsince = age - liveness.initialDelay();
            if (lsince >= 0 && lsince % liveness.period() == 0) {
                if (appUp) failures = 0;
                else if (++failures >= liveness.failureThreshold()) {
                    restarts++; containerStart = t; failures = 0; ready = false;
                    System.out.printf("t=%3d s  liveness failed %d times: container KILLED%n",
                            t, liveness.failureThreshold());
                }
            }
        }
        System.out.println("restarts in " + horizon + " s: " + restarts);
    }

    public static void main(String[] args) {
        Probe liveness = new Probe(10, 5, 3);
        run("A: 45 s start-up, liveness only (initialDelay 10, period 5, failures 3)",
                45, null, liveness, 120);
        run("B: 45 s start-up, startup probe (period 5, failures 12)",
                45, new Probe(0, 5, 12), liveness, 120);
    }
}

