import java.util.*;
import java.util.concurrent.*;

public class LogMdcDemo {
    /** Minimal MDC: a per-thread map, as in SLF4J. */
    static final ThreadLocal<Map<String, String>> MDC = ThreadLocal.withInitial(HashMap::new);

    static void log(String msg) {
        System.out.printf("[%-14s] traceId=%s  %s%n", Thread.currentThread().getName(),
                MDC.get().getOrDefault("traceId", "-"), msg);
    }

    /** Wraps a task so the submitting thread's MDC is copied to the worker (TaskDecorator idea). */
    static Runnable withMdc(Runnable task) {
        Map<String, String> captured = new HashMap<>(MDC.get());
        return () -> {
            Map<String, String> previous = MDC.get();
            MDC.set(captured);
            try { task.run(); } finally { MDC.set(previous); }
        };
    }

    static String sanitise(String s) { return s.replaceAll("[\\r\\n]", "_"); }

    public static void main(String[] args) throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(1, r -> new Thread(r, "async-1"));
        MDC.get().put("traceId", "4bf92f35");
        log("request received");

        pool.submit(() -> log("plain async task")).get();              // MDC is lost
        pool.submit(withMdc(() -> log("decorated async task"))).get(); // MDC propagated
        pool.shutdown();

        String userInput = "bob\n2026-10-19 10:00:00 INFO  admin logged in";
        System.out.println("--- log injection");
        System.out.println("raw      : login failed for " + userInput);
        System.out.println("sanitised: login failed for " + sanitise(userInput));
    }
}

import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

public class AsyncLogDemo {
    static void slowSink() { try { Thread.sleep(1); } catch (InterruptedException e) { } }

    public static void main(String[] args) throws Exception {
        int lines = 2000;

        long t0 = System.nanoTime();
        for (int i = 0; i < lines; i++) slowSink();
        System.out.printf("synchronous        : caller blocked %4d ms, 0 dropped%n", ms(t0));

        for (String policy : new String[]{"discard", "block"}) {
            BlockingQueue<Integer> queue = new ArrayBlockingQueue<>(256);
            AtomicInteger written = new AtomicInteger(), dropped = new AtomicInteger();
            Thread writer = new Thread(() -> {
                try { while (true) { queue.take(); slowSink(); written.incrementAndGet(); } }
                catch (InterruptedException e) { }
            });
            writer.setDaemon(true); writer.start();
            t0 = System.nanoTime();
            for (int i = 0; i < lines; i++) {
                if (policy.equals("block")) queue.put(i);
                else if (!queue.offer(i)) dropped.incrementAndGet();
            }
            System.out.printf("async, queue 256, %-7s: caller blocked %4d ms, %d dropped%n",
                    policy, ms(t0), dropped.get());
            writer.interrupt();
        }
    }
    static long ms(long t0) { return (System.nanoTime() - t0) / 1_000_000; }
}

