import java.util.concurrent.atomic.AtomicLong;
import org.slf4j.Logger;

public final class ThrottledLog {

    private final Logger log;
    private final long intervalNanos;
    private final AtomicLong lastLogged = new AtomicLong(System.nanoTime() - Long.MAX_VALUE / 2);
    private final AtomicLong suppressed = new AtomicLong();

    public ThrottledLog(Logger log, long intervalSeconds) {
        this.log = log;
        this.intervalNanos = intervalSeconds * 1_000_000_000L;
    }

    public void error(String message, Throwable cause) {
        long now = System.nanoTime();
        long last = lastLogged.get();
        if (now - last >= intervalNanos && lastLogged.compareAndSet(last, now)) {
            log.error("{} (suppressed {} similar events)", message, suppressed.getAndSet(0), cause);
        } else {
            suppressed.incrementAndGet();
        }
    }
}

import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

public class Saturation {
    public static void main(String[] args) throws Exception {
        int threads = 10, serviceMs = 100;       // capacity: 10 / 0.1 s = 100 requests per second
        ThreadPoolExecutor pool = new ThreadPoolExecutor(threads, threads, 0, TimeUnit.SECONDS,
                new LinkedBlockingQueue<>());
        AtomicLong totalLatency = new AtomicLong();
        AtomicInteger done = new AtomicInteger();
        int[] ratePerSecond = {80, 80, 130, 130, 130, 80, 80, 80};       // offered load per second
        System.out.println(" t(s) offered  active  queued  mean latency so far (ms)");
        for (int sec = 0; sec < ratePerSecond.length; sec++) {
            long start = System.nanoTime();
            for (int i = 0; i < ratePerSecond[sec]; i++) {
                long submitted = System.nanoTime();
                pool.execute(() -> {
                    try { Thread.sleep(serviceMs); } catch (InterruptedException e) { }
                    totalLatency.addAndGet((System.nanoTime() - submitted) / 1_000_000);
                    done.incrementAndGet();
                });
                long next = start + (long) ((i + 1) * 1e9 / ratePerSecond[sec]);
                while (System.nanoTime() < next) Thread.sleep(1);
            }
            int d = done.get();
            System.out.printf("%5d %7d %7d %7d  %d%n", sec + 1, ratePerSecond[sec],
                    pool.getActiveCount(), pool.getQueue().size(),
                    d == 0 ? 0 : totalLatency.get() / d);
        }
        pool.shutdownNow();
    }
}

import java.util.*;
import java.util.concurrent.*;

public class ThreadsVsVirtual {
    static final int REQUESTS = 2000;
    static final int BLOCK_MS = 200;                       // stands for a database or HTTP call

    static long run(ExecutorService pool) throws Exception {
        long t0 = System.nanoTime();
        List<Future<?>> futures = new ArrayList<>();
        for (int i = 0; i < REQUESTS; i++) {
            futures.add(pool.submit(() -> { Thread.sleep(BLOCK_MS); return null; }));
        }
        for (Future<?> f : futures) f.get();
        pool.shutdown();
        return (System.nanoTime() - t0) / 1_000_000;
    }

    public static void main(String[] args) throws Exception {
        System.out.println("requests = " + REQUESTS + ", each blocks " + BLOCK_MS + " ms");
        long platform = run(Executors.newFixedThreadPool(200));
        System.out.printf("platform pool of 200 threads : %5d ms  (ideal %d ms)%n",
                platform, REQUESTS / 200 * BLOCK_MS);
        long virtual = run(Executors.newVirtualThreadPerTaskExecutor());
        System.out.printf("virtual thread per request   : %5d ms  (ideal %d ms)%n",
                virtual, BLOCK_MS);
    }
}

