import java.util.*;

public class CacheLeak {
    /** Bounded cache: evicts the least recently used entry (idea of Caffeine maximumSize). */
    static class Lru<K, V> extends LinkedHashMap<K, V> {
        final int max;
        Lru(int max) { super(16, 0.75f, true); this.max = max; }
        @Override protected boolean removeEldestEntry(Map.Entry<K, V> e) { return size() > max; }
    }

    public static void main(String[] args) {
        boolean bounded = args.length > 0 && args[0].equals("bounded");
        Map<String, byte[]> cache = bounded ? new Lru<>(500) : new HashMap<>();
        Runtime rt = Runtime.getRuntime();
        System.out.println("mode=" + (bounded ? "bounded(500)" : "unbounded")
                + ", max heap " + rt.maxMemory() / (1 << 20) + " MB");
        try {
            for (int i = 1; i <= 20_000; i++) {
                cache.put("order-" + i, new byte[20 * 1024]);             // 20 KB per entry
                if (i % 500 == 0) {
                    System.gc();
                    System.out.printf("requests=%5d  entries=%5d  heap after GC=%3d MB%n", i,
                            cache.size(), (rt.totalMemory() - rt.freeMemory()) >> 20);
                }
            }
            System.out.println("finished without error");
        } catch (OutOfMemoryError e) {
            int entries = cache.size();
            cache.clear();                                       // free memory before printing
            System.out.println("OutOfMemoryError after " + entries + " entries: " + e.getMessage());
        }
    }
}
